+            DataType.INTEGER,
+            DataType.LONG,
+            DataType.DOUBLE,
+            DataType.DATETIME,
+            DataType.BOOLEAN,
+            DataType.IP,
+            DataType.VERSION,
+            DataType.KEYWORD,
+            DataType.TEXT
