+
+            // With precision
+            for (var precisionCaseSupplier : precisionSuppliers) {
+                suppliers.add(makeSupplier(emptyFieldSupplier, precisionCaseSupplier));
+            }
+
+            // Without precision
+            suppliers.add(makeSupplier(emptyFieldSupplier));
+        }
