+            }
+
+            @Override
+            public boolean matches(Object item) {
+                if (item instanceof Iterable<?> == false) {
+                    return false;
+                }
+
+                var castedItem = (Iterable<?>) item;
+
+                return matcher.matches(castedItem);
+            }
+        };
